$string['copykoha'] = 'Pour passer à Koha, le logiciel libre de bibliothèque.

catalogo.mrc : les notices en MARC 21 avec les exemplaires dans le champ 952. À charger dans « Outils > Préparer les notices MARC pour l\'importation », puis au moment d\'importer, lui indiquer d\'ajouter les exemplaires.

lectores.csv : les lecteurs, dans l\'« Importation de lecteurs » de Koha, avec leur carte. Il faut d\'abord créer dans Koha la bibliothèque (le code de la colonne branchcode, également en $a et $b de chaque 952) et les catégories ST, T, S et PT, ainsi que les types d\'exemplaires BK et REF.

prestamos.koc : les livres actuellement sortis, dans « Circulation > Téléverser un fichier de circulation hors ligne ». À charger en dernier, une fois les lecteurs et les exemplaires déjà intégrés.';
$string['copymade'] = 'Sauvegarde effectuée.';
$string['copymake'] = 'Faire une sauvegarde maintenant';
$string['copyreadme'] = 'Sauvegarde des bibliothèques de {$a->entity}, réalisée le {$a->date} par Oksigenia Ayvurenda {$a->release}.

Chaque fichier CSV est une table, avec le nom des colonnes sur la première ligne. Ils s\'ouvrent avec n\'importe quel tableur.

- entity, library : l\'entité et ses bibliothèques.
- record, authority, recauth : le catalogue (titres, auteurs, sujets…).
- item : les exemplaires et le matériel, avec leurs codes.
- reader, member : les lecteurs et leur classe pour chaque année scolaire.
- loan : les prêts, en cours et retournés.
- hold : les réservations, en attente, mises de côté et terminées.
- stocktake, stockread : les récolements et ce qui a été lu dans chacun.
- withdrawal, withdrawn : les procès-verbaux de désherbage et leurs exemplaires.
- lot, lotitem : les lots entre bibliothèques et leurs exemplaires.
- digital : les versions numériques des notices (sans leurs fichiers, qui restent sur le site).
- rule, year, tutor, source : règles de prêt, années scolaires, professeurs principaux et origine de chaque ligne.
- catalogo.mrc et catalogo.xml : le catalogue en MARC 21 (ISO 2709 et MARCXML), avec ses exemplaires dans le champ 852, pour l\'importer dans n\'importe quel logiciel de bibliothèque.
- catalogo-dc.xml : le catalogue en Dublin Core, pour les dépôts et catalogues qui ne lisent pas le MARC.
- catalogo.ris : le catalogue en RIS, pour les gestionnaires de références comme Zotero ou Mendeley.
- challenge, wish : les défis des classes et leurs demandes.
- review, roomread : les avis et les lectures sur place.
- bankset, banktitle : les lots de la banque de manuels scolaires et leurs titres.
- koha/ : la même chose, préparée pour Koha (voir son LISEZMOI).

Les couvertures et le fonds numérique vont dans une autre sauvegarde, celle des fichiers. Les voix enregistrées ne quittent pas le serveur.

Lignes de chaque fichier :
{$a->counts}
';
