$string['helpbank01'] = 'Un lot correspond à ce qui est prêté à chaque élève de certaines classes : ses titres et les classes auxquelles il est destiné.';
$string['helpbank02'] = 'Chaque titre indique combien d\'exemplaires sont sortis et combien sont disponibles ; s\'il n\'y en a pas assez pour tout le monde, cela s\'affiche en rouge.';
$string['helpbank03'] = 'Pour ajouter un titre au lot, recherchez-le par son titre ou son ISBN.';
$string['helpbank04'] = 'Un nouveau lot : son nom et les classes qui l\'utilisent. Chaque élève de ces classes attend tous ses titres.';
$string['helpbank05'] = 'Par classe : chaque classe, avec qui attend des livres et qui les a.';
$string['helpbank06'] = 'Dans une classe, chaque élève avec ce qu\'il a et ce qui lui manque. À la banque de prêt, son lot apparaît en scannant sa carte, avec le contrat pour la famille.';
$string['helpbankround01'] = 'C\'est ici que l\'on gère la collecte de fin d\'année scolaire : combien de livres manquent à l\'appel et combien sont déjà revenus.';
$string['helpbankround02'] = 'Indiquez la date limite. Les rappels la mentionneront.';
$string['helpbankround03'] = 'En un clic, chaque lecteur reçoit un rappel avec ses livres, et chaque professeur principal, la liste des élèves de sa classe qui en ont. Au maximum une fois par jour.';
$string['helpbankround04'] = 'Chaque classe, avec ce qui est sorti. Ouvrez-en une pour voir qui a quoi.';
$string['helpbankround05'] = 'Si un livre ne revient pas, notez-le comme perdu. La banque de manuels ne facture rien : elle indique ce qui manque et chez qui.';
$string['helpbankround06'] = 'S\'il réapparaît, un clic le remet sur le rayonnage.';
$string['helpbankround07'] = 'Et au début de l\'année scolaire, la distribution : qui attend des livres et combien d\'exemplaires manquent dans chaque lot.';
$string['helpbankround08'] = 'Chaque classe a sa liste et ses contrats, à imprimer et à faire signer par les familles.';
$string['helpcard01'] = 'Voici la carte d\'un lecteur, telle qu\'il la voit : sur son téléphone, en classe ou sur l\'ordinateur de la bibliothèque.';
$string['helpcard02'] = 'Sa fleur grandit au fil de ses passages à la banque de prêt : revenir, explorer de nouveaux coins, donner son avis sur un livre et terminer ce qu\'il commence. Elle ne fane jamais.';
$string['helpcard03'] = 'Le code de la carte se scanne à la banque de prêt comme un livre : avec la douchette, la caméra ou le téléphone.';
$string['helpcard04'] = 'Il voit ici par quels chemins elle grandit, sans chiffres ni comparaisons avec les autres.';
$string['helpcard05'] = 'Dès douze ans, le ciel remplace la fleur, et chacun peut choisir l\'aspect classique. Vous pouvez la voir comme il la verrait.';
$string['helpcard06'] = 'Voilà comment un lecteur de collège la voit : la même carte, avec un autre aspect.';
$string['helpcard07'] = 'Pour les imprimer, « Imprimer les cartes » dans Lecteurs : pour tout l\'établissement, un cycle ou une classe, chacune avec son visuel.';
$string['helpcardprint01'] = 'D\'abord, pour qui : tous les lecteurs ou une partie. Une carte isolée s\'imprime depuis la fiche du lecteur.';
$string['helpcardprint02'] = 'Le visuel de chaque carte, selon l\'âge du lecteur. « Modifier » en applique un pour tous ou un différent selon les âges.';
$string['helpcardprint03'] = 'Le logo apparaît en haut à droite sur chaque carte.';
$string['helpcardprint04'] = 'Où les imprimer : chez un imprimeur, sur des cartes en plastique, sur des planches de cartes ou sur du papier ordinaire. Chaque option adapte le PDF au bon format.';
$string['helpcardprint05'] = 'Ce qu\'indique le verso : l\'adresse et quelques lignes sur la bibliothèque, identiques pour tous.';
$string['helpcardprint06'] = 'Et « Préparer ». S\'ils sont peu nombreux, ils se téléchargent aussitôt ; s\'ils sont nombreux, ils sont générés en arrière-plan et s\'affichent dans « Prêts ».';
$string['helpdesk01'] = 'Voici la banque de prêt : un seul champ, toujours prêt. La douchette y écrit toute seule, et vous pouvez aussi taper au clavier.';
$string['helpdesk02'] = 'Ana arrive avec un livre. D\'abord, sa carte.';
$string['helpdesk03'] = 'Sa fiche s\'ouvre : ce qu\'elle a chez elle et si un prêt est en retard.';
$string['helpdesk04'] = 'Maintenant le livre. Il est prêté, avec sa date de retour, et un signal sonore retentit.';
$string['helpdesk05'] = 'En cas d\'erreur, « Annuler » remet tout comme avant.';
$string['helpdesk06'] = 'Noa rapporte un livre. Pour enregistrer le retour, il suffit de scanner le livre : pas besoin de la carte.';
$string['helpdesk07'] = 'Il est en retard : la banque de prêt l\'indique et enregistre le retour quand même.';
$string['helpdesk08'] = 'Au retour, une appréciation en un clic : elle a adoré, elle ne l\'a pas fini ou elle en veut d\'autres comme ça.';
$string['helpdesk09'] = 'Noa veut d\'autres livres comme ça : cliquez sur « En veut d\'autres comme ça ».';
$string['helpdesk10'] = 'Rien de plus simple. Ce qui est prêté, retourné et noté alimente les rappels et les chiffres de l\'année scolaire.';
