$string['helpformats05'] = 'Sur la fiche d\'un lecteur, vous pouvez indiquer qu\'il a besoin de formats accessibles : il verra ceux du fonds numérique signalés ainsi, et personne d\'autre.';
$string['helpframe'] = 'L\'écran en pratique';
$string['helpfree01'] = 'Deux sources d\'œuvres du domaine public : Project Gutenberg, très riche en anglais, et Wikisource, avec de nombreuses œuvres en espagnol et dans d\'autres langues.';
$string['helpfree02'] = 'Écrivez un titre ou un auteur, puis lancez la recherche.';
$string['helpfree03'] = 'Choisissez une œuvre : vous verrez qui l\'a écrite et ce qu\'indiquent ses droits.';
$string['helpfree04'] = 'Indiquez à qui elle s\'adresse, et qu\'elle est bien dans le domaine public dans votre pays : chaque pays compte les années à partir de la mort de l\'auteur.';
$string['helpfree05'] = '« L\'importer dans le catalogue », et elle s\'y installe avec sa notice et son livre, à lire ici, dans la bibliothèque. Une œuvre volumineuse prend un peu de temps.';
$string['helpholds01'] = 'En haut, les exemplaires mis de côté : le livre est déjà à la banque de prêt, où il attend son lecteur jusqu\'à cette date.';
$string['helpholds02'] = 'En dessous, la file d\'attente : qui attend chaque livre et combien de personnes passent avant.';
$string['helpholds03'] = 'Quand le livre revient, la banque de prêt vous le signale à l\'enregistrement du retour : il est mis de côté, et son lecteur reçoit un avis.';
$string['helpholds04'] = '« Annuler » retire quelqu\'un de la file d\'attente ou libère l\'exemplaire mis de côté.';
$string['helpholds05'] = 'Et l\'on décide ici de la façon de réserver : à la banque de prêt, toujours ; en ligne, si vous le souhaitez et pour qui vous voulez.';
$string['helpill01'] = 'Quand un livre n\'est pas là et qu\'une autre bibliothèque le possède, vous gardez le fil ici : ce que vous demandez et ce que vous prêtez.';
$string['helpill02'] = 'Le titre, la bibliothèque à laquelle vous le demandez et, s\'il est pour quelqu\'un, sa carte.';
$string['helpill03'] = 'enregistrez la demande avec « Demander un livre ».';
$string['helpill04'] = 'Dès qu\'il arrive, cochez-le, en indiquant la date à laquelle il faut le rendre. La personne qui l\'attend reçoit un avis.';
$string['helpill05'] = 'Et si une autre bibliothèque vous en demande un, vous le lui prêtez d\'ici. À son retour, vous le passez par la banque de prêt.';
$string['helpimport01'] = 'C\'est ici qu\'entre votre catalogue : un fichier MARC de votre logiciel habituel, une feuille de calcul enregistrée en CSV ou un export d\'Abies Web.';
$string['helpimport02'] = 'Déposez-le ici ou choisissez-le, et le système passe tout seul à l\'étape suivante. Rien n\'a encore été importé.';
$string['helpimport03'] = 'D\'abord, les chiffres de tout le fichier : titres, exemplaires, emplacements et ceux arrivés sans code.';
$string['helpimport04'] = 'Et les premiers livres, debout sur leur étagère, avec leur étiquette de cote : voilà à quoi ils ressembleront.';
$string['helpimport05'] = 'Chaque colonne est reconnue par son nom. Celle qui n\'est pas reconnue reste de côté, sans gêner.';
$string['helpimport06'] = 'Si l\'une d\'elles a été mal interprétée, on la corrige ici en voyant ce qu\'elle contient, et l\'étagère est redessinée.';
$string['helpimport07'] = 'quand tout est prêt, lancez l\'import.';
$string['helpimport08'] = 'C\'est importé. Si vous réimportez le même fichier, il met à jour ce qui s\'y trouvait sans rien créer en double.';
$string['helpimport09'] = 'Et voici la suite : consulter le catalogue, imprimer les étiquettes, importer les lecteurs et ouvrir la banque de prêt.';
$string['helpintroadd'] = 'Une minute pour ajouter des livres par leur ISBN, dans une bibliothèque d\'entraînement : rien de vos données n\'est modifié.';
$string['helpintrobank'] = 'Comment créer un lot de manuels scolaires et voir, classe par classe, qui a quoi, dans une banque de manuels d\'entraînement.';
$string['helpintrobankround'] = 'Comment gérer le retour de fin d\'année et la distribution de la suivante, dans une banque de manuels d\'entraînement.';
$string['helpintrocard'] = 'Une minute avec la carte d\'un lecteur fictif de la bibliothèque d\'entraînement : comment il la voit, ce qui la fait grandir et comment elle passe à la banque de prêt.';
$string['helpintrocardprint'] = 'Comment imprimer les cartes : pour qui, avec quel modèle et où, dans la bibliothèque d\'entraînement.';
$string['helpintrodesk'] = 'Une minute à la banque de prêt, dans une bibliothèque d\'entraînement avec des lecteurs et des livres fictifs : rien de vos données n\'est modifié.';
$string['helpintroformats'] = 'Une lectrice a demandé un livre audio. Rien n\'est enregistré : c\'est la bibliothèque d\'entraînement.';
$string['helpintrofree'] = 'Importer dans le catalogue une œuvre du domaine public, avec son texte, pour la lire dans la bibliothèque. Rien ne vient de l\'extérieur : c\'est la bibliothèque d\'entraînement.';
$string['helpintroholds'] = 'Ce qui est mis de côté, qui attend et comment réserver. Tout se passe dans la bibliothèque d\'entraînement, avec des lecteurs d\'exemple.';
$string['helpintroill'] = 'Demander un livre à une autre bibliothèque et lui en prêter un. Rien n\'est enregistré : c\'est la bibliothèque d\'entraînement.';
$string['helpintroimport'] = 'Importer un catalogue complet depuis un autre logiciel. Tout se passe dans la bibliothèque d\'entraînement, avec un fichier d\'exemple : votre catalogue ne bouge pas.';
$string['helpintrokeepers'] = 'Choisir qui tient une bibliothèque : un enseignant, le professeur principal ou un élève bibliothécaire, à sa propre banque de prêt. Rien n\'est enregistré : c\'est la bibliothèque d\'entraînement.';
$string['helpintrokeeperslay'] = 'Choisir qui tient une bibliothèque, à sa propre banque de prêt. Rien n\'est enregistré : c\'est la bibliothèque d\'entraînement.';
$string['helpintrolabels'] = 'Une minute pour imprimer des étiquettes et des étiquettes de cote, avec des livres fictifs de la bibliothèque d\'entraînement.';
$string['helpintrolate'] = 'Qui a un livre en retard et comment le relancer. Tout se passe dans la bibliothèque d\'entraînement, avec des lecteurs d\'exemple : personne n\'est relancé.';
$string['helpintromaterial'] = 'Enregistrer ce qui se prête et qui n\'est pas un livre. Rien n\'est enregistré : c\'est la bibliothèque d\'entraînement.';
$string['helpintromyclass'] = 'Une minute avec la page du professeur principal, avec deux classes fictives de la bibliothèque d\'entraînement.';
$string['helpintropurchases'] = 'Des demandes des lecteurs à la commande en librairie. Rien n\'est enregistré : c\'est la bibliothèque d\'entraînement.';
$string['helpintroreaders'] = 'Qui fréquente votre bibliothèque, comment trouver un lecteur et d\'où ils viennent. Tout se passe dans la bibliothèque d\'entraînement, avec des lecteurs d\'exemple.';
$string['helpintroreaderslist'] = 'Inscrire les lecteurs depuis une feuille de calcul. Tout se passe dans la bibliothèque d\'entraînement, avec une liste d\'exemple.';
$string['helpintrorecord'] = 'Comment corriger la notice d\'un livre et ses exemplaires, dans la bibliothèque d\'entraînement.';
$string['helpintroreports'] = 'Une minute avec les six rapports de la bibliothèque, sur les prêts fictifs de la bibliothèque d\'entraînement.';
$string['helpintroreviews'] = 'Une minute pour publier des avis, avec deux avis fictifs de la bibliothèque d\'entraînement.';
$string['helpintrorules'] = 'Combien de temps et combien de livres à la fois, et pour qui. Tout se passe dans la bibliothèque d\'entraînement : vos règles ne changent pas.';
$string['helpintrosanctions'] = 'Simple rappel, jours sans prêt ou amende. Rien n\'est enregistré : c\'est la bibliothèque d\'entraînement.';
$string['helpintroselfloan'] = 'Créer un poste de prêt en libre-service et faire le tour de ce qu\'on y fait. Rien n\'est enregistré : c\'est la bibliothèque d\'entraînement.';
$string['helpintrostacks'] = 'Une minute dans les rayonnages de la bibliothèque d\'entraînement : les dos, l\'étiquette de cote, les espaces libres et le pupitre.';
$string['helpintrotutors'] = 'Attribuer le professeur principal de chaque classe. Rien n\'est enregistré : c\'est la bibliothèque d\'entraînement.';
$string['helpintrotwins'] = 'Fusionner deux fiches d\'une même personne. Rien n\'est enregistré : c\'est la bibliothèque d\'entraînement.';
$string['helpintrovoices'] = 'Ce qu\'il faut vérifier avant que d\'autres n\'écoutent une voix enregistrée. Tout se passe dans la bibliothèque d\'entraînement, avec une voix d\'exemple.';
$string['helpintroweed'] = 'Retirer de la collection ce qui ne sert plus, avec son procès-verbal. Tout se passe dans la bibliothèque d\'entraînement : votre collection ne change pas.';
$string['helpintrowishes'] = 'Une demi-minute avec le livre demandé par une classe fictive de la bibliothèque d\'entraînement.';
$string['helpkeepers01'] = 'On choisit ici qui tient cette bibliothèque : un enseignant du département, le professeur principal de la classe ou un élève bibliothécaire.';
$string['helpkeepers01lay'] = 'On choisit ici qui tient cette bibliothèque : la personne qui s\'occupe de cette salle, quelqu\'un du service ou un bénévole.';
$string['helpkeepers02'] = 'Recherchez un lecteur de l\'établissement par son nom : il doit avoir un compte.';
$string['helpkeepers03'] = '« La lui confier », et il peut alors tenir la banque de prêt de cette bibliothèque, et uniquement celle-là : ses livres et, pour une bibliothèque de classe, les lecteurs de ses classes.';
$string['helpkeepers03lay'] = '« La lui confier », et il peut alors tenir la banque de prêt de cette bibliothèque, et uniquement celle-là.';
$string['helpkeepers04'] = 'Pour la lui retirer, cliquez sur « Retirer ». L\'équipe de l\'établissement conserve ses accès habituels.';
$string['helplabels01'] = 'Étiquettes avec code-barres pour l\'intérieur du livre, ou étiquettes de cote pour le dos.';
$string['helplabels02'] = 'Vous choisissez lesquels : les exemplaires ajoutés aujourd\'hui, ceux depuis une date donnée ou des codes précis.';
$string['helplabels03'] = 'Par exemple, deux livres d\'après leur code.';
$string['helplabels04'] = 'Voici comment ils apparaissent, sur la planche d\'étiquettes de votre choix.';
$string['helplabels05'] = 'Si vous avez déjà entamé une planche, commencez sur la première case libre : aucune étiquette n\'est perdue.';
$string['helplabels06'] = 'Et pour finir, « Imprimer » : de préférence à 100 % et sans marges.';
$string['helplate01'] = 'Les prêts les plus anciens d\'abord. Ces cartes comptent le nombre d\'exemplaires dans chaque tranche et permettent de filtrer.';
$string['helplate02'] = 'Chaque encadré indique son nombre de lecteurs et le retard le plus important ; en rouge au-delà de trente jours.';
$string['helplate03'] = 'Ouvrez-le pour voir qui a quoi.';
$string['helplate04'] = 'Le nom mène à sa fiche, avec tout ce qu\'il a en prêt.';
$string['helplate05'] = 'La liste peut être imprimée, et le bouton de rappel envoie la relance immédiatement, sans attendre.';
$string['helplate06'] = 'Les avis de retard partent déjà automatiquement chaque jour : cet outil sert si vous souhaitez prendre les devants.';
$string['helpmaterial01'] = 'Ce qui se prête et n\'est pas un livre passe par ici : ordinateurs portables, tablettes, calculatrices, appareils photo ou jeux. D\'abord, son nom.';
$string['helpmaterial02'] = 'Le nombre d\'unités. Chacune porte son étiquette et se prête séparément.';
$string['helpmaterial03'] = 'Au besoin, indiquez ici la marque, le modèle, les numéros de série ou les étiquettes déjà présentes.';
$string['helpmaterial04'] = 'ajoutez-les avec « Ajouter ».';
$string['helpmaterial05'] = 'Les voilà créées, avec leurs codes. À la banque de prêt, elles s\'empruntent comme un livre, et leur état se note d\'un simple geste au départ comme au retour.';
$string['helpmyclass01'] = '« Ma classe » est la page du professeur principal : le défi de chaque trimestre, le jardin de la classe et leurs lectures, sans aucun nom.';
$string['helpmyclass02'] = 'Quand la classe réussit son défi, quelque chose pousse dans son jardin, et le crieur l\'annonce sur la page d\'accueil des lecteurs.';
$string['helpmyclass03'] = 'Et la récompense, c\'est encore plus de lecture : avec votre classe, vous choisissez le prochain livre de la bibliothèque.';
$string['helpmyclass04'] = 'Vous l\'envoyez à la bibliothèque, et vous verrez ici quand il arrive.';
$string['helpmyclass05'] = 'Dans une classe qui ne l\'a pas encore relevé, vous choisissez le défi de ce trimestre : coins, raconter ou que chacun emporte un livre. Ou aucun.';
$string['helpmyclass06'] = 'choisissez « Raconter » pour 5º B.';
$string['helpmyclass07'] = 'Tout se mesure à la banque de prêt : vous ne notez rien, et on ne dit jamais qui.';
$string['helpnav'] = 'Comment ça marche ?';
$string['helpnosuch'] = 'Cette aide guidée n\'existe pas.';
$string['helpnotplayable'] = 'Cette aide guidée montre quelque chose que cette bibliothèque n\'a pas.';
$string['helpnow'] = 'À vous :';
$string['helppurchases01'] = 'Voici ce que demandent les lecteurs : le titre, et qui le demande.';
$string['helppurchases02'] = 'En haut, ce que vous avez dépensé cette année. Le budget s\'indique si vous voulez.';
$string['helppurchases03'] = 'Si vous allez l\'acheter : combien, à quel prix et à qui. Le prix n\'est pas nécessaire.';
$string['helppurchases04'] = 'dites oui avec « L\'acheter ».';
$string['helppurchases05'] = 'Ce que vous allez acheter est regroupé par librairie.';
$string['helppurchases06'] = 'passez la commande.';
$string['helppurchases07'] = 'Voici le bon de commande, à envoyer ou à imprimer.';
$string['helppurchases08'] = 'Quand il arrive, cochez-le dans « Commandes ». En l\'ajoutant avec son ISBN, la personne qui l\'a demandé reçoit une notification.';
$string['helpreaders01'] = 'Les voici tous, en deux chiffres : combien de lecteurs et combien de classes.';
$string['helpreaders01lay'] = 'Les voici tous : combien de lecteurs compte la bibliothèque.';
$string['helpreaders02'] = 'Pour en trouver un, son nom ou sa carte.';
$string['helpreaders03'] = 'Chaque cycle, avec ses classes, et combien de lecteurs compte chacune. Cliquez sur une classe pour afficher ses lecteurs.';
$string['helpreaders03lay'] = 'Et ici, tous, par soixante. Le nom mène à sa fiche.';
$string['helpreaders04'] = 'Pour en ajouter d\'autres, « Importer des lecteurs ».';
$string['helpreaders05'] = 'Chaque endroit d\'où ils peuvent venir, et s\'il est utilisé : une liste, votre logiciel de gestion ou votre plateforme d\'apprentissage.';
$string['helpreaders05lay'] = 'Chaque endroit d\'où ils peuvent provenir, et s\'il est utilisé : une liste ou les comptes de cette plateforme.';
$string['helpreaders06'] = 'Vous pouvez en utiliser plusieurs. Ce qui arrive chaque nuit n\'a pas besoin d\'être importé à la main.';
$string['helpreaderslist01'] = 'Un tableur enregistré en CSV, avec une ligne par lecteur et les en-têtes sur la première. Glissez-le ici, ou collez-le.';
$string['helpreaderslist02'] = 'Avant que quiconque n\'arrive : combien de lecteurs la liste contient, dans combien de classes, et combien ont une adresse e-mail.';
$string['helpreaderslist03'] = 'Et les premiers, avec leur nom et leur classe.';
$string['helpreaderslist04'] = 'Les colonnes sont reconnues automatiquement. Si l\'une d\'elles a été mal comprise, corrigez-la ici.';
$string['helpreaderslist05'] = 'quand tout est prêt, inscrivez-les.';
$string['helpreaderslist06'] = 'C\'est fait. Si vous chargez à nouveau la liste, elle met à jour ceux qui sont déjà là sans faire de doublons.';
$string['helprecord01'] = 'Sur la notice d\'un livre, « Corriger cette notice » ouvre tout ce que le catalogue dit de lui.';
$string['helprecord02'] = 'Le titre, les auteurs, un par ligne, l\'ISBN, l\'édition, le résumé : modifiez ce qui ne va pas.';
$string['helprecord03'] = 'En écrivant un sujet, ceux que la bibliothèque utilise déjà apparaissent : ainsi, pas de doublons presque identiques.';
$string['helprecord04'] = '« Enregistrer », et la notice est corrigée. Ses exemplaires restent comme ils étaient.';
$string['helprecord05'] = 'Chaque exemplaire a son bouton « Corriger » : le code, l\'étiquette de cote, l\'emplacement et ses notes.';
$string['helprecord06'] = 'Et « Supprimer cet exemplaire », uniquement pour ce qui a été ajouté par erreur. Ce qui a déjà été prêté est retiré dans « Désherbage ».';
$string['helpreports01'] = 'Six rapports fixes, toujours les mêmes, pour le bilan de l\'année ou pour l\'équipe pédagogique.';
$string['helpreports01lay'] = 'Six rapports fixes, toujours les mêmes, pour le bilan de l\'année ou pour la direction de la bibliothèque.';
$string['helpreports02'] = 'Ceux d\'une période se choisissent en touchant une feuille : cette semaine, ce mois-ci, un trimestre, l\'année scolaire, ou « Autre » pour aller d\'un mois à l\'autre.';
$string['helpreports03'] = 'Chaque ligne, avec son chiffre et une barre pour comparer d\'un coup d\'œil.';
$string['helpreports04'] = 'Tous se téléchargent en CSV, pour les ouvrir avec n\'importe quel tableur.';
$string['helpreports05'] = 'Et l\'année scolaire en chiffres, pour le bilan de fin d\'année.';
$string['helpreports05lay'] = 'Et l\'année en chiffres, pour le bilan de la bibliothèque.';
$string['helpreviews01'] = 'Voici ce que racontent les lecteurs sur les livres qu\'ils ont empruntés : une phrase ou un dessin.';
$string['helpreviews02'] = 'Qui l\'a écrit et quand. Tant qu\'il n\'est pas publié, seule l\'équipe le voit.';
$string['helpreviews03'] = '« Publier » l\'affiche sur la notice du livre, avec la signature définie dans les paramètres de l\'établissement, et uniquement pour ses lecteurs.';
$string['helpreviews04'] = 'S\'il ne doit pas paraître, « Ne pas publier » : son auteur peut en écrire un autre.';
$string['helpreviews05'] = 'publiez l\'avis de Leo.';
$string['helpreviews06'] = 'Publié : il compte sur le chemin « raconter » de sa fleur. Quand de nouveaux avis arrivent, la banque de prêt l\'indique et Moodle vous prévient une fois par jour.';
$string['helprules01'] = 'Chaque règle se lit comme une phrase : qui, quoi, combien à la fois et pendant combien de temps.';
$string['helprules02'] = '« Modifier » n\'ouvre que cette règle, et le reste ne change pas.';
$string['helprules03'] = 'Pour une exception, une nouvelle règle : ici, trente jours pour les enseignants.';
$string['helprules03lay'] = 'Pour une exception, une nouvelle règle : ici, trente jours pour l\'équipe.';
$string['helprules04'] = 'enregistrez-la.';
$string['helprules05'] = 'Il y en a maintenant deux, et la plus précise l\'emporte : les enseignants ont la leur ; tous les autres, la règle générale.';
$string['helprules05lay'] = 'Il y en a maintenant deux, et la plus précise l\'emporte : l\'équipe a la sienne ; tous les autres, la règle générale.';
$string['helprules06'] = 'Un prêt déjà effectué conserve sa date : la règle s\'applique à partir du suivant.';
$string['helpsanctions01'] = 'Vous décidez ici de ce qu\'entraîne un livre rendu en retard. Par défaut, juste un avertissement.';
$string['helpsanctions02'] = 'Il peut entraîner des jours sans prêt : pour chaque jour de retard, une période sans pouvoir emprunter de livres.';
$string['helpsanctions03'] = 'Ou une amende : un montant par jour, avec un plafond. Elle est seulement notée ici ; elle se règle à la banque de prêt.';
$string['helpsanctions04'] = 'enregistrez.';
$string['helpsanctions05'] = 'Cela se lit comme une phrase. Désormais, tout livre rendu en retard l\'applique en passant par la banque de prêt.';
$string['helpsanctions06'] = 'La banque de prêt vous avertit avant de prêter, mais le dernier mot vous revient : vous pouvez toujours prêter quand même.';
$string['helpselfloan01'] = 'Un poste est une tablette ou un ordinateur où chaque lecteur emprunte lui-même ses livres, avec sa carte.';
$string['helpselfloan02'] = 'Donnez-lui le nom de l\'endroit où il se trouve.';
$string['helpselfloan03'] = 'créez-le avec « Créer le poste ».';
$string['helpselfloan04'] = 'Cette adresse ouvre le poste. Ouvrez-la sur place, sans vous connecter avec un compte. Elle n\'apparaît que maintenant.';
$string['helpselfloan05'] = 'Vous choisissez ici qui peut l\'utiliser et si l\'on peut aussi y rendre des livres.';
$string['helpselfloan06'] = 'Et ici, vous passez en revue ce qui a été fait sur les postes. Ce qui ne convient pas, vous l\'annulez.';
$string['helpskip'] = 'Passer à la fin';
$string['helpstacks01'] = 'Chaque livre est un dos, aussi haut et épais que le vrai, de la couleur de sa couverture. Ils sont rangés dans le même ordre que dans la bibliothèque.';
$string['helpstacks02'] = 'En bas se trouve l\'étiquette de cote : le numéro du sujet, trois lettres de l\'auteur et trois du titre. Elle permet de trouver le livre sur le vrai rayonnage.';
$string['helpstacks03'] = 'Un espace vide est un livre que quelqu\'un a emporté chez lui : il est en voyage.';
$string['helpstacks04'] = 'touchez un dos pour sortir le livre de l\'étagère.';
$string['helpstacks05'] = 'Sur le pupitre : sa couverture, son emplacement et son étiquette de cote. « Voir la notice » mène à tout le reste.';
$string['helpstacks06'] = '« Remettre à sa place » le replace sur l\'étagère. Au clavier, les flèches parcourent l\'étagère, Entrée sort le livre et Échap le remet.';
$string['helpstacks07'] = '« Tous les emplacements » revient aux emplacements et aux coins de la bibliothèque, pour commencer par un autre.';
